  const [wide] = wideIds.map(id => write(dir, record({ runId: id, mode: 'aa', baseline: 'uplot', candidate: 'uplot', runs: timedRuns(MIN_BAND_PAIRS, k => 10 + (k % 10), k => 10 + ((k * 7 + 3) % 10)) })));
