    if (lib.PRODUCTION && lib.stylesheetPlugin && lib.stylesheets) { define = lib.PRODUCTION; base = [lib.stylesheetPlugin((await lib.stylesheets()).minified)]; recipe = 'scripts/build.mjs'; }
  }
